[[gnu::flatten, gnu::noinline]]
void kernel_floyd_warshall(std::size_t n, auto path) {
	using namespace noarr;

	// A dummy 1D structure used only to traverse k in [0, n)
	auto k_struct = noarr::scalar<char>() ^ k_vec ^ noarr::set_length<'k'>(n);

	// Reuse a traverser for the path matrix across all k-iterations.
	auto path_trav = noarr::traverser(path);

#pragma scop
	// Outer loop: k = 0 .. n-1
	traverser(k_struct).for_each([&](auto sk) {
		const std::size_t k = get_index<'k'>(sk);

		// View representing the k-th row: path[k][j] for all j
		// (dimension 'i' is fixed to k, only 'j' remains visible)
		auto row_k = path ^ noarr::fix<'i'>(k);

		// Middle loop over i in row-major order.
		// for_dims<'i'> creates an outer loop over 'i';
		// the inner traverser ti will then iterate 'j'.
		path_trav.template for_dims<'i'>([&](auto ti) {
			// State with the current i fixed; contains only 'i'
			auto s_i = ti.state();

			// Load path[i][k] once per (k, i) and treat it as loop-invariant
			// with respect to j. For this benchmark, all edge weights are
			// non-negative, thus path[k][k] >= 0 for all k and the update
			// at j == k:
			//   path[i][k] = min(path[i][k], path[i][k] + path[k][k])
			// is a no-op. Therefore path[i][k] does not change within the
			// j-loop and can be cached safely.
			auto s_ik = s_i + noarr::idx<'j'>(k); // state for (i, k)
			const num_t pik = path[s_ik];         // path[i][k]

			// Inner loop over j: iterate the remaining dimension 'j'
			// for this fixed i (row-major: i outer, j inner).
			ti.for_each([&](auto s_ij) {
				// s_ij contains both 'i' and 'j'
				num_t &pij = path[s_ij]; // path[i][j]

				// row_k has only dimension 'j'; the extra 'i' in s_ij is
			 // ignored by the layout, so we can index it directly by s_ij.
				const num_t pkj = row_k[s_ij]; // path[k][j]

				const num_t via_k = pik + pkj;

				// Standard Floyd–Warshall relaxation
				pij = (pij < via_k) ? pij : via_k;
			});
		});
	});
#pragma endscop
